// ----------------------------------------------------------------------------------------------- events
export type EventEnvelope = { id: string; occurredAt: string; accountId: string | null; correlationId: string | null; };
export interface EventPayloads {
  "account.active_changed": { previous: string | null; current: string | null; };
  "account.archived": Record<string, never>;
  "account.connected": { server: string; currency: string; environment: Environment; };
  "account.created": { name: string; provider: string; environment: Environment; };
  "account.disconnected": { reason: string; };
  "account.error": { code: string; detail: string; };
  "account.rules_changed": { versionId: string; deferred: boolean; reasons: GuardReason[]; };
  "account.snapshot": { snapshot: AccountSnapshot; };
  "account.trading_toggled": { enabled: boolean; };
  "account.updated": { fields: string[]; };
  "agent.connected": { status: AgentStatus; };
  "agent.disconnected": { agentLogin: string; };
  "agent.heartbeat": { agentId: string; latencyMs: number; };
  "agent.status_changed": { status: AgentStatus; };
  "autonomy.armed": { mode: AutonomyMode; leaseUntil: string | null; readiness: ReadinessReport | null; };
  "autonomy.disarmed": { mode: AutonomyMode; reason: string; };
  "autonomy.halted": { reason: string; };
  "autonomy.mode_changed": { previous: AutonomyMode; current: AutonomyMode; reason: string; leaseUntil: string | null; };
  "autonomy.readiness_changed": { readiness: ReadinessReport; };
  "execution.acknowledged": { commandId: string; status: "ACCEPTED" | "REJECTED" | "DUPLICATE" | "EXPIRED"; reason: string | null; };
  "execution.command_created": { command: ExecutionCommand; };
  "execution.command_sent": { commandId: string; loginHint: string | null; };
  "execution.failed": { commandId: string; detail: string; brokerRetcode: string | null; };
  "execution.reconciled": { commandId: string; outcome: "executed" | "rejected"; source: "agent" | "core"; brokerOrderId: string | null; brokerPositionId: string | null; filledVolume: number | null; averagePrice: number | null; detail: string; };
  "execution.rejected": { commandId: string; code: string; detail: string; };
  "execution.reported": { commandId: string; outcome: "executed" | "simulated"; symbol: string; side: Side | null; filledVolume: number | null; averagePrice: number | null; brokerOrderId: string | null; brokerPositionId: string | null; detail: string; replayed: boolean; };
  "execution.unknown": { commandId: string; detail: string; };
  "market.calendar_updated": { releases: UpcomingRelease[] | null; syncedAt: string | null; };
  "market.candle_closed": { candle: Candle; };
  "market.tick": { tick: Tick; };
  "position.closed": { trade: ClosedTrade; };
  "position.modified": { positionId: string; field: "volume" | "stop_loss" | "take_profit"; previous: number; current: number; };
  "position.opened": { positionId: string; symbol: string; side: Side; volume: number; entryPrice: number; stopLoss: number; takeProfit: number; openedAt: string; reconstructed: boolean; };
  "positions.snapshot": { positions: Position[]; };
  "reconciliation.completed": { mismatches: number; critical: number; positionsChecked: number; readable: boolean; };
  "reconciliation.mismatch": { mismatch: Mismatch; };
  "reconciliation.started": Record<string, never>;
  "risk.approved": { decision: RiskDecision; };
  "risk.evaluation_started": { intentId: string | null; };
  "risk.lockout_acknowledged": { lockoutId: string; acknowledgedAt: string; };
  "risk.lockout_cleared": { lockoutId: string | null; clearedBy: string; };
  "risk.lockout_enabled": { lockoutId: string; reason: string; since: string; until: string | null; };
  "risk.lockout_violated": { brokerPositionId: string; symbol: string; side: Side; lockoutId: string; lockoutReason: string; openedAt: string; };
  "risk.rejected": { decision: RiskDecision; };
  "risk.state_updated": { risk: RiskStatus; };
  "strategy.evaluation_completed": { strategyId: string; symbol: string; outcome: "proposed" | "blocked"; stage: string | null; detail: string | null; eventAt: string; };
  "strategy.evaluation_started": { strategyId: string; symbol: string; };
  "system.health_changed": { status: Severity; findings: Finding[]; };
  "system.heartbeat": { seq: number; uptimeSeconds: number; };
  "system.heartbeat_missed": { component: string; ageSeconds: number | null; };
  "system.incident_opened": { incident: Incident; };
  "system.incident_resolved": { incident: Incident; };
  "system.snapshot": { serverTime: string; version: string; activeAccountId: string | null; accounts: Account[]; autonomy: AutonomyOverview; health: HealthDigest; calendar: CalendarSnapshot; accountStates: Record<string, AccountState>; };
  "trade.intent_created": { intent: TradeIntent; };
  "trade.rejected": { intentId: string; stage: "risk" | "execution"; reasons: string[]; };
}
export type EventType = keyof EventPayloads;
export type CockpitEvent = { [K in EventType]: { type: K; payload: EventPayloads[K] } & EventEnvelope }[EventType];

